

const LEVABOTA_VERSION='0.3.40', LEVABOTA_BUILD='0340';
const $=id=>document.getElementById(id);let current=null,source='none',pendingGPX=null,map=null,routeLine=null,poiMarkers=[],qrStream=null,qrTimer=null,qrTarget='create',manageMode=false,selectedWalks=new Set(),actualMap=null,actualRouteLine=null,actualPoiMarkers=[];const R=6371;
function view(id){['home','create','detail','poiEditor','finalize'].forEach(x=>$(x).classList.toggle('hidden',x!==id));document.body.classList.toggle('final-theme',id==='finalize'||id==='poiEditor')}function showHome(){view('home');renderWalks()}function showCreate(){$('createTitle').textContent='Planear caminhada';$('createSubtitle').textContent='Começamos apenas pelo essencial.';resetCreateButton();source='none';pendingGPX=null;$('place').value='';$('date').value='';$('time').value='09:00';$('distance').value='';$('people').value='2';$('routeurl').value='';$('gpxstatus').innerHTML='';$('qrstatus').innerHTML='';document.querySelectorAll('.sourcebtn').forEach(b=>b.classList.toggle('active',b.dataset.source==='none'));['gpxbox','qrbox','linkbox'].forEach(x=>$(x).classList.add('hidden'));view('create')}
function chooseSource(s,b){source=s;document.querySelectorAll('.sourcebtn').forEach(x=>x.classList.remove('active'));b.classList.add('active');['gpxbox','qrbox','linkbox'].forEach(x=>$(x).classList.add('hidden'));if(s!=='none')$(s+'box').classList.remove('hidden')}
function getWalks(){return JSON.parse(localStorage.getItem('walks')||'[]')}function setWalks(a){localStorage.setItem('walks',JSON.stringify(a))}
function hav(a,b){const dlat=(b.lat-a.lat)*Math.PI/180,dlon=(b.lon-a.lon)*Math.PI/180,la1=a.lat*Math.PI/180,la2=b.lat*Math.PI/180;const h=Math.sin(dlat/2)**2+Math.cos(la1)*Math.cos(la2)*Math.sin(dlon/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
async function readGPX(file){if(!file)return;try{pendingGPX=await parseGPXFile(file);$('distance').value=pendingGPX.dist.toFixed(1);let extra=pendingGPX.waypoints?.length?` · ${pendingGPX.waypoints.length} locais`:'';$('gpxstatus').innerHTML=`<div class='fileok'>✓ ${escapeHtml(file.name)} · ${pendingGPX.dist.toFixed(1)} km · +${Math.round(pendingGPX.up)} m${extra}</div>`}catch(e){pendingGPX=null;$('gpxstatus').innerHTML=`<div class='notice warn'>Não consegui ler este GPX. Experimenta outro ficheiro.</div>`}}
async function readQR(file){if(!file)return;const st=$('qrstatus');st.innerHTML=`<div class='notice'>A ler QR…</div>`;try{if(!('BarcodeDetector'in window))throw new Error('unsupported');const det=new BarcodeDetector({formats:['qr_code']});const bmp=await createImageBitmap(file),codes=await det.detect(bmp);if(!codes.length)throw new Error('none');const raw=codes[0].rawValue||'';$('routeurl').value=raw;st.innerHTML=`<div class='fileok'>✓ QR reconhecido</div><div class='notice'>${escapeHtml(raw)}</div>`}catch(e){st.innerHTML=`<div class='notice warn'>${e.message==='unsupported'?'Este navegador não permite leitura automática de QR nesta versão. Podes colar a ligação manualmente.':'Não encontrei um QR legível nesta imagem.'}</div>`}}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function saveWalk(){const w={id:Date.now(),place:$('place').value.trim(),date:$('date').value,time:$('time').value,distance:+$('distance').value,people:+$('people').value,source,routeurl:$('routeurl').value.trim()};if(!w.place||!w.date||!w.distance){alert('Preenche local, data e distância.');return}if(w.distance>80&&!confirm('Este percurso parece ser de longa duração. A LevaBota está otimizada para caminhadas de 1 a 2 dias. Se vais preparar apenas uma etapa, indica de preferência a distância dessa etapa. Queres guardar assim mesmo?'))return;if(pendingGPX){w.gpx=pendingGPX}const a=getWalks();a.unshift(w);setWalks(a);openWalk(w.id)}
function walkDisplayName(w){if(w?.completed&&w?.finalName&&String(w.finalName).trim())return String(w.finalName).trim();if(w?.completed){const r=w?.actualGpx?.routeName||w?.gpx?.routeName;if(r&&String(r).trim())return String(r).trim()}return w?.place||'Caminhada'}
function renderWalks(){const a=getWalks();$('count').textContent=a.length?`${a.length} guardada${a.length>1?'s':''}`:'';$('walks').className=a.length?'':'empty';if(!a.length){$('walks').innerHTML='Ainda não tens caminhadas guardadas.';return}const rows=a.map(w=>`<div class="walkrow">${manageMode?`<input class="walkcheck" type="checkbox" ${selectedWalks.has(w.id)?'checked':''} onchange="toggleWalkSelection(${w.id},this.checked)">`:''}<div class="walkmain" ${manageMode?'onclick="toggleWalkByRow('+w.id+')"':'onclick="openWalk('+w.id+')"'}><b>${escapeHtml(walkDisplayName(w))}</b><div class="summary">${fmtDate(w.date)} · ${(+w.distance).toFixed(1)} km · ${w.people} pessoa${w.people>1?'s':''}${w.gpx?' · GPX ✓':''}${w.completed?' · Concluída ✓':''}</div></div></div>`).join('');const tools=manageMode?`<div class="homeManage"><p class="managehint">Seleciona uma caminhada para editar ou uma ou mais para eliminar.</p><div class="selectionbar"><button class="btn secondary small" onclick="editSelectedWalk()">${iconInline('edit')}Editar</button><button class="btn danger small" onclick="deleteSelectedWalks()">${iconInline('trash')}Eliminar</button></div></div>`:'';$('walks').innerHTML=rows+tools}
function fmtDate(s){return new Intl.DateTimeFormat('pt-PT',{weekday:'short',day:'numeric',month:'short'}).format(new Date(s+'T12:00:00'))}

function toggleManageMode(){if(!manageMode){manageMode=true;selectedWalks.clear();view('home');$('navHome').classList.remove('active');$('navManage').innerHTML=iconNav('check')+'<small>Concluir</small>';$('navManage').classList.add('active');renderWalks();setTimeout(()=>document.querySelector('.managehint')?.scrollIntoView({behavior:'smooth',block:'nearest'}),50);return}manageMode=false;selectedWalks.clear();$('navManage').innerHTML=iconNav('manage')+'<small>Gerir</small>';$('navManage').classList.remove('active');$('navHome').classList.add('active');renderWalks()}
function toggleWalkSelection(id,on){on?selectedWalks.add(id):selectedWalks.delete(id);renderWalks()}
function toggleWalkByRow(id){selectedWalks.has(id)?selectedWalks.delete(id):selectedWalks.add(id);renderWalks()}
function editSelectedWalk(){if(selectedWalks.size!==1){alert(selectedWalks.size?'Para editar, seleciona apenas uma caminhada.':'Seleciona uma caminhada para editar.');return}const id=[...selectedWalks][0];manageMode=false;selectedWalks.clear();$('navManage').innerHTML=iconNav('manage')+'<small>Gerir</small>';$('navManage').classList.remove('active');openWalk(id);editCurrent()}
function deleteSelectedWalks(){if(!selectedWalks.size){alert('Seleciona pelo menos uma caminhada para eliminar.');return}const a=getWalks(),names=a.filter(w=>selectedWalks.has(w.id)).map(w=>walkDisplayName(w));const msg=selectedWalks.size===1?`Eliminar “${names[0]}”? Esta ação elimina os dados guardados neste dispositivo.`:`Eliminar ${selectedWalks.size} caminhadas selecionadas? Esta ação não pode ser anulada.`;if(!confirm(msg))return;setWalks(a.filter(w=>!selectedWalks.has(w.id)));selectedWalks.clear();renderWalks()}

function openWalk(id){current=getWalks().find(x=>x.id===id);if(!current)return;$('dplace').textContent=walkDisplayName(current);$('dmeta').textContent=`${fmtDate(current.date)} · ${current.time} · ${(+current.distance).toFixed(1)} km · ${current.people} pessoas`;renderPreparation(current);renderSavedWeather(current);renderRouteDocument(current);renderPanelPhoto();renderPostWalkCard(current);view('detail');setTimeout(()=>renderRoute(current.primaryRoute==='actual'&&current.actualGpx?{...current,gpx:current.actualGpx}:current),80)}

function renderPostWalkCard(w){const box=$('postWalkCard');if(!box)return;if(!w.completed){box.innerHTML=`<b>Depois da caminhada</b><p class='summary'>Quando terminares, completa o percurso realmente feito e regista como correu.</p><button class='btn secondary' onclick='showFinalize()'>✓ Finalizar caminhada</button>`;return}const diff={easier:'Mais fácil do que esperava',expected:'Como esperava',harder:'Mais difícil do que esperava'}[w.feltDifficulty]||'';box.innerHTML=`<div class='titleline'><b>✓ Caminhada concluída</b><span class='summary'>Memória guardada</span></div>${diff?`<p class='summary'><b>Como correu:</b> ${escapeHtml(diff)}</p>`:''}${w.walkNotes?`<p class='summary'><b>Notas:</b> ${escapeHtml(w.walkNotes)}</p>`:''}<button class='btn secondary' onclick='showFinalize()'>✎ Rever / editar finalização</button>`}
function showFinalize(){if(!current)return;$('finalizeTitle').textContent=current.place+' · '+fmtDate(current.date);$('finalDifficulty').value=current.feltDifficulty||'';$('finalNotes').value=current.walkNotes||'';renderActualGpxStatus();const fn=$('finalWalkName');if(fn){fn.value=current.finalName||current.actualGpx?.routeName||current.gpx?.routeName||current.place||'';fn.dataset.edited=''}$('finalSaved').textContent='';renderPanelPhoto();view('finalize');window.scrollTo(0,0)}
function backToDetail(){if(current)openWalk(current.id);else showHome()}
let poiEditTarget='planned',poiPhotoIndex=-1,pendingBulkPhotos=[];
function poiState(p){return p.lbState||'visible'}
function poiLabel(p){return (p.lbName||p.name||'Local').trim()||'Local'}
function poiPhotos(p){if(Array.isArray(p.lbPhotos))return p.lbPhotos;if(p.lbPhotoKey){p.lbPhotos=[{key:p.lbPhotoKey,name:p.lbPhotoName||'Fotografia'}];delete p.lbPhotoKey;delete p.lbPhotoName;return p.lbPhotos}return []}
async function photoDigest(ph){try{const blob=await docGet(ph.key);if(!blob)return 'meta:'+[(ph.name||''),(ph.size||''),(ph.date||'')].join('|');if(crypto?.subtle){const b=await blob.arrayBuffer(),h=await crypto.subtle.digest('SHA-256',b);return 'sha256:'+Array.from(new Uint8Array(h)).map(x=>x.toString(16).padStart(2,'0')).join('')}return 'meta:'+[(ph.name||''),blob.size,(ph.date||'')].join('|')}catch(e){return 'key:'+ph.key}}
async function dedupePoiPhotos(p){const arr=poiPhotos(p);if(arr.length<2)return 0;const seen=new Set(),keep=[];let removed=0;for(const ph of arr){const sig=await photoDigest(ph);if(seen.has(sig)){removed++;continue}seen.add(sig);keep.push(ph)}if(removed)p.lbPhotos=keep;return removed}
async function repairDuplicatePhotos(){if(!current)return 0;let removed=0;for(const g of [current.gpx,current.actualGpx]){for(const p of (g?.waypoints||[]))removed+=await dedupePoiPhotos(p)}if(removed)persistCurrent();return removed}
function hasPoiPhotos(p){return poiPhotos(p).length>0}
function activePois(g){return (g?.waypoints||[]).map((p,i)=>({p,i})).filter(x=>poiState(x.p)!=='hidden')}
function routeForEdit(){return poiEditTarget==='actual'?current.actualGpx:current.gpx}
function poiDraftKey(){return current?`levabota-poi-draft-${current.id}-${poiEditTarget}`:''}
const POI_SESSION_KEY='levabota-poi-active-session';
function savePoiSession(){if(!current)return;try{localStorage.setItem(POI_SESSION_KEY,JSON.stringify({walkId:current.id,target:poiEditTarget,scrollY:Math.round(window.scrollY||0),updatedAt:Date.now()}))}catch(e){}}
function clearPoiSession(){try{localStorage.removeItem(POI_SESSION_KEY)}catch(e){}}
function readPoiSession(){try{return JSON.parse(localStorage.getItem(POI_SESSION_KEY)||'null')}catch(e){return null}}
function savePoiDraft(){const g=routeForEdit();if(!g||!current)return;try{localStorage.setItem(poiDraftKey(),JSON.stringify({walkId:current.id,target:poiEditTarget,updatedAt:Date.now(),waypoints:g.waypoints||[]}))}catch(e){}}
function clearPoiDraft(){try{localStorage.removeItem(poiDraftKey())}catch(e){}}
function restorePoiDraft(){const g=routeForEdit();if(!g||!current)return false;try{const raw=localStorage.getItem(poiDraftKey());if(!raw)return false;const d=JSON.parse(raw);if(d.walkId!==current.id||d.target!==poiEditTarget||!Array.isArray(d.waypoints)||d.waypoints.length!==g.waypoints.length)return false;g.waypoints=d.waypoints;return true}catch(e){return false}}
async function openPoiEditor(target){if(!current)return;poiEditTarget=target;const g=routeForEdit();if(!g?.waypoints?.length){alert('Este percurso não contém locais para editar.');return}const removed=await repairDuplicatePhotos();const recovered=restorePoiDraft();$('poiEditorSubtitle').textContent=(target==='actual'?'Percurso realizado':'Percurso planeado')+' · '+g.waypoints.length+' locais';$('bulkPhotoBox').classList.toggle('hidden',target!=='actual');pendingBulkPhotos=[];$('bulkPhotoMatches').innerHTML=(removed?`<div class='notice'>Limpeza automática: ${removed} fotografia${removed===1?' repetida removida':'s repetidas removidas'}. As fotografias únicas foram preservadas.</div>`:'')+(recovered?`<div class='notice warn'><b>Edição recuperada ✓</b> Retomámos as alterações que ainda não tinhas finalizado.</div>`:'');renderPoiEditor();view('poiEditor');savePoiSession();window.scrollTo(0,0)}
function closePoiEditor(){pendingBulkPhotos.forEach(x=>x.url&&URL.revokeObjectURL(x.url));pendingBulkPhotos=[];clearPoiSession();showFinalize()}
async function renderPoiEditor(){const g=routeForEdit(),box=$('poiEditorList');box.innerHTML='';for(let i=0;i<g.waypoints.length;i++){const p=g.waypoints[i],state=poiState(p),photos=poiPhotos(p),card=document.createElement('div');card.className='poiEditCard';card.innerHTML=`<div class='poiEditTop'><span>${state==='highlight'?'⭐':photos.length?'📷':'📍'}</span><input type='text' value='${escapeHtml(poiLabel(p))}' aria-label='Nome do local' onchange='renamePoi(${i},this.value)'></div><div class='poiState'><button class='${state==='visible'?'on':''}' onclick="setPoiState(${i},'visible')">📍 Visível</button><button class='${state==='highlight'?'on':''}' onclick="setPoiState(${i},'highlight')">⭐ Destaque</button><button class='${state==='hidden'?'on':''}' onclick="setPoiState(${i},'hidden')">◌ Oculto</button></div><div class='poiPhotoRow' id='poiPhotoRow${i}'><div class='poiPhotoPlaceholder'>📷</div><button class='btn secondary' onclick='pickPoiPhoto(${i})'>Adicionar fotografias</button>${photos.length?`<button class='btn danger' style='flex:0 0 auto;width:auto' onclick='removeAllPoiPhotos(${i})'>Remover</button>`:''}</div><div class='poiPhotos' id='poiPhotos${i}'></div>`;box.appendChild(card);if(photos.length)loadPoiThumbs(i,photos)}}
function savePoiEdit(){savePoiDraft()}
function renamePoi(i,v){const p=routeForEdit()?.waypoints?.[i];if(!p)return;p.lbName=(v||'').trim();savePoiEdit()}
function setPoiState(i,state){const p=routeForEdit()?.waypoints?.[i];if(!p)return;p.lbState=state;savePoiEdit();renderPoiEditor()}
function pickPoiPhoto(i){poiPhotoIndex=i;let inp=$('poiPhotoPicker');if(!inp){inp=document.createElement('input');inp.id='poiPhotoPicker';inp.type='file';inp.accept='image/*';inp.multiple=true;inp.className='hidden';inp.onchange=()=>{savePoiPhotos(inp.files);inp.value=''};document.body.appendChild(inp)}inp.value='';inp.click()}
async function optimizePhoto(file){return new Promise((ok,fail)=>{const img=new Image(),u=URL.createObjectURL(file);img.onload=()=>{try{const max=1600,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);c.toBlob(b=>{URL.revokeObjectURL(u);b?ok(b):fail(Error('blob'))},'image/jpeg',.82)}catch(e){URL.revokeObjectURL(u);fail(e)}};img.onerror=()=>{URL.revokeObjectURL(u);fail(Error('image'))};img.src=u})}
async function savePoiPhotos(files){if(!files?.length||poiPhotoIndex<0)return;const p=routeForEdit()?.waypoints?.[poiPhotoIndex];if(!p)return;const arr=poiPhotos(p);try{for(const file of files){const blob=await optimizePhoto(file),key=`walk-${current.id}-${poiEditTarget}-poi-${poiPhotoIndex}-photo-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;await docPut(key,blob);arr.push({key,name:file.name,size:blob.size})}p.lbPhotos=arr;await dedupePoiPhotos(p);p.lbState=p.lbState==='hidden'?'visible':p.lbState;savePoiEdit();renderPoiEditor()}catch(e){alert('Não foi possível guardar uma das fotografias neste dispositivo.')}}
async function removeAllPoiPhotos(i){const p=routeForEdit()?.waypoints?.[i];if(!p)return;p.lbPhotos=[];savePoiEdit();renderPoiEditor()}
async function loadPoiThumbs(i,photos){const row=$('poiPhotoRow'+i),box=$('poiPhotos'+i);if(!box)return;box.innerHTML='';for(let j=0;j<photos.length;j++){const ph=photos[j];try{const blob=await docGet(ph.key);if(!blob)continue;const u=URL.createObjectURL(blob),wrap=document.createElement('div');wrap.className='poiPhotoItem';wrap.innerHTML=`<img src='${u}' title='${escapeHtml(ph.name||'Fotografia')}'><div class='poiPhotoActions'><button type='button' onclick='movePoiPhoto(${i},${j})'>📍 Mover</button><button type='button' class='danger' onclick='removePoiPhoto(${i},${j})'>Remover</button></div>`;box.appendChild(wrap)}catch(e){}}if(row){const ph=row.querySelector('.poiPhotoPlaceholder');if(ph&&photos.length){ph.textContent='📷 '+photos.length}}}
function movePoiPhoto(fromIndex,photoIndex){const g=routeForEdit(),from=g?.waypoints?.[fromIndex],photo=poiPhotos(from)[photoIndex];if(!g||!from||!photo)return;const options=g.waypoints.map((p,i)=>`${i+1}. ${poiLabel(p)}`).join('\n');const raw=prompt(`Mover esta fotografia para que local?\n\n${options}`,String(fromIndex+1));if(raw===null)return;const toIndex=parseInt(raw,10)-1;if(!Number.isInteger(toIndex)||toIndex<0||toIndex>=g.waypoints.length){alert('Escolhe um número válido da lista.');return}if(toIndex===fromIndex)return;from.lbPhotos=poiPhotos(from).filter((_,j)=>j!==photoIndex);const to=g.waypoints[toIndex],arr=poiPhotos(to);arr.push(photo);to.lbPhotos=arr;if(to.lbState==='hidden')to.lbState='visible';savePoiEdit();renderPoiEditor()}
function removePoiPhoto(i,j){const p=routeForEdit()?.waypoints?.[i],arr=poiPhotos(p);if(!p||!arr[j])return;if(!confirm('Remover esta fotografia da caminhada?'))return;p.lbPhotos=arr.filter((_,x)=>x!==j);savePoiEdit();renderPoiEditor()}
async function attachPoiPopupPhoto(marker,p){const photos=poiPhotos(p);if(!photos.length)return;try{const blob=await docGet(photos[0].key);if(!blob)return;const u=URL.createObjectURL(blob),more=photos.length>1?`<br><small>+${photos.length-1} fotografia${photos.length>2?'s':''}</small>`:'',html=`<b>${escapeHtml(poiLabel(p))}</b>${p.desc?`<br>${escapeHtml(p.desc)}`:''}<img class='poiPopupPhoto' src='${u}'>${more}`;marker.bindPopup(html)}catch(e){}}
function parseExifLocalMs(v){const m=String(v||'').match(/^(\d{4}):(\d{2}):(\d{2})\s+(\d{2}):(\d{2}):(\d{2})/);if(!m)return NaN;return new Date(+m[1],+m[2]-1,+m[3],+m[4],+m[5],+m[6]).getTime()}
function nearestActualTrack(ms){const pts=current?.actualGpx?.pts||[];if(!pts.length||!Number.isFinite(ms))return null;let best=null;for(const p of pts){if(!Number.isFinite(p.ms))continue;const d=Math.abs(p.ms-ms);if(!best||d<best.dt)best={...p,dt:d}}return best}
function nearestWaypointForPhoto(ms,track){const ws=current?.actualGpx?.waypoints||[];let best=null;for(let i=0;i<ws.length;i++){const w=ws[i];let score=Infinity,why='posição';if(Number.isFinite(ms)&&Number.isFinite(w.ms)){score=Math.abs(w.ms-ms)/1000;why='hora'}else if(track){score=havM(track.lat,track.lon,w.lat,w.lon);why='posição'}if(!best||score<best.score)best={i,score,why}}return best}
async function prepareBulkPhotos(fileList){const files=[...fileList||[]];if(!files.length)return;if(!(current?.actualGpx?.pts||[]).some(p=>Number.isFinite(p.ms))){alert('Para localizar automaticamente as fotografias, volta a importar uma vez o percurso realizado nesta versão. Assim a LevaBota guarda também as horas do GPX.');return}pendingBulkPhotos=[];const box=$('bulkPhotoMatches');box.innerHTML='<div class="notice">A analisar fotografias…</div>';for(const file of files){const ex=await exifReadJpeg(file),ms=parseExifLocalMs(ex.date),track=nearestActualTrack(ms),wp=nearestWaypointForPhoto(ms,track),url=URL.createObjectURL(file);pendingBulkPhotos.push({file,url,date:ex.date,ms,track,wpIndex:wp?.i??0,delta:track?Math.round(track.dt/1000):null})}renderBulkMatches()}
function renderBulkMatches(){const g=current.actualGpx,box=$('bulkPhotoMatches');box.innerHTML=`<div class='notice'><b>${pendingBulkPhotos.length} fotografia${pendingBulkPhotos.length===1?'':'s'}</b> analisada${pendingBulkPhotos.length===1?'':'s'}. Confirma os locais antes de guardar.</div>`+pendingBulkPhotos.map((x,i)=>`<div class='photoMatch'><div class='photoMatchTop'><img src='${x.url}'><div><b>${escapeHtml(x.file.name)}</b><br><small>${x.date?escapeHtml(x.date):'Sem hora EXIF'}${x.delta!=null?` · diferença ${x.delta}s`:''}</small></div></div><select onchange='pendingBulkPhotos[${i}].wpIndex=+this.value'>${g.waypoints.map((p,j)=>`<option value='${j}' ${j===x.wpIndex?'selected':''}>${escapeHtml(poiLabel(p))}</option>`).join('')}</select></div>`).join('')+`<button class='btn secondary' onclick='confirmBulkPhotos()'>✓ Confirmar associação das fotografias</button>`}
async function confirmBulkPhotos(){if(!pendingBulkPhotos.length)return;try{for(const x of pendingBulkPhotos){const p=current.actualGpx.waypoints[x.wpIndex],blob=await optimizePhoto(x.file),key=`walk-${current.id}-actual-poi-${x.wpIndex}-photo-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;await docPut(key,blob);const arr=poiPhotos(p);arr.push({key,name:x.file.name,size:blob.size,date:x.date||null});p.lbPhotos=arr;await dedupePoiPhotos(p);if(p.lbState==='hidden')p.lbState='visible'}pendingBulkPhotos.forEach(x=>URL.revokeObjectURL(x.url));pendingBulkPhotos=[];$('bulkPhotoMatches').innerHTML=`<div class='notice'>Fotografias associadas ✓ Agora podes ajustar nomes e ⭐ destaques. No fim toca em <b>Guardar alterações</b>.</div>`;savePoiDraft();renderPoiEditor()}catch(e){alert('Não foi possível guardar todas as fotografias.')}}
function finalizePoiEdits(){const g=routeForEdit();if(!g)return;try{for(const p of g.waypoints){if(hasPoiPhotos(p)){if(p.lbState!=='highlight')p.lbState='visible'}else if(p.lbState!=='highlight')p.lbState='hidden'}persistCurrent();clearPoiDraft();clearPoiSession();alert('Alterações guardadas ✓');closePoiEditor()}catch(e){alert('Não foi possível concluir a gravação. A edição ficou guardada como rascunho para continuares depois.');savePoiDraft()}}
function renderActualGpxStatus(){const el=$('actualGpxStatus'),box=$('actualRouteView'),info=$('actualGpxInfo');if(!el||!box)return;if(!current?.actualGpx){el.innerHTML='';if(info)info.innerHTML='';box.classList.add('hidden');if(actualMap){actualMap.remove();actualMap=null}return}const g=current.actualGpx,allPois=g.waypoints||[],pois=activePois(g);el.innerHTML=`<div class='fileok'>✓ ${escapeHtml(g.name||'Percurso realizado')} · ${g.dist.toFixed(1)} km · +${Math.round(g.up)} m</div>`;box.classList.remove('hidden');$('adist').textContent=g.dist.toFixed(1)+' km';$('aup').textContent='+'+Math.round(g.up)+' m';$('adown').textContent='−'+Math.round(g.down)+' m';if(info){if(allPois.length){info.innerHTML=`<div class='gpxabout'><div class='poirow'><b>Locais do percurso realizado — ${pois.length} visíveis / ${allPois.length} guardados</b>${pois.length?`<ul id='actualPoiList' class='poiList ${pois.length>8?'collapsed':''}'>${pois.map(x=>`<li class='${poiState(x.p)==='highlight'?'poiHighlight':''}' onclick='focusActualPoi(${x.i})'><span class='poidot'></span><span>${escapeHtml(poiLabel(x.p))}${poiState(x.p)==='highlight'?` <span class="poistar">★</span>`:''}${hasPoiPhotos(x.p)?' 📷':''}</span></li>`).join('')}</ul>${pois.length>8?`<button id='actualPoiToggle' class='poitoggle' onclick='toggleActualPois()'>Ver todos (${pois.length})</button>`:''}`:`<div class='notice warn'>Os locais continuam guardados, mas estão todos ocultos. Podes recuperá-los em Editar locais.</div>`}<button class='btn secondary small poiEditBtn' onclick="openPoiEditor('actual')">✎ Editar locais</button></div></div>`}else{info.innerHTML=`<p class='summary' style='margin-top:10px'>Este GPX realizado não contém locais/waypoints.</p>`}};drawElevTo(g,'actualElev');setTimeout(()=>drawActualMap(g),80);$('useActualBtn').textContent=current.primaryRoute==='actual'?'✓ Percurso realizado é o principal':'Usar percurso realizado como principal'}
function drawActualMap(g){if(typeof L==='undefined'){setTimeout(()=>drawActualMap(g),180);return}if(actualMap){actualMap.remove();actualMap=null}actualPoiMarkers=[];actualMap=L.map('actualMap',{zoomControl:true});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(actualMap);const ll=g.pts.map(p=>[p.lat,p.lon]);actualRouteLine=L.polyline(ll,{weight:5,color:'#A84F2A',opacity:.9}).addTo(actualMap);L.circleMarker(ll[0],{radius:7,color:'#5B3426',fillColor:'#F4EBDD',fillOpacity:1,weight:3}).addTo(actualMap).bindTooltip('Início');L.circleMarker(ll[ll.length-1],{radius:7,color:'#5B3426',fillColor:'#A84F2A',fillOpacity:1,weight:3}).addTo(actualMap).bindTooltip('Fim');const pinIcon=p=>L.divIcon({className:'poi-pin'+(hasPoiPhotos(p)?' photoPin':''),html:'',iconSize:[16,16],iconAnchor:[8,15],popupAnchor:[0,-14]});actualPoiMarkers=[];(g.waypoints||[]).forEach((p,i)=>{if(poiState(p)==='hidden'){actualPoiMarkers[i]=null;return}const m=L.marker([p.lat,p.lon],{icon:pinIcon(p),title:poiLabel(p),opacity:poiState(p)==='highlight'?1:.82}).addTo(actualMap).bindPopup(`<b>${escapeHtml(poiLabel(p))}${poiState(p)==='highlight'?' ★':''}</b>${p.desc?`<br>${escapeHtml(p.desc)}`:''}`);actualPoiMarkers[i]=m;attachPoiPopupPhoto(m,p)});actualMap.fitBounds(actualRouteLine.getBounds(),{padding:[15,15]})}
