function drawElevTo(g,id){const c=$(id),ctx=c.getContext('2d'),pts=g.pts.filter(p=>Number.isFinite(p.ele));ctx.clearRect(0,0,c.width,c.height);if(pts.length<2){ctx.fillText('GPX sem dados de elevação',20,50);return}const min=Math.min(...pts.map(p=>p.ele)),max=Math.max(...pts.map(p=>p.ele)),pad=22,w=c.width-pad*2,h=c.height-pad*2;ctx.strokeStyle='#dfe4de';ctx.lineWidth=1;for(let i=0;i<4;i++){let y=pad+i*h/3;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(c.width-pad,y);ctx.stroke()}ctx.strokeStyle='#A84F2A';ctx.lineWidth=3;ctx.beginPath();pts.forEach((p,i)=>{let x=pad+(p.d/g.dist)*w,y=pad+(1-(p.ele-min)/(max-min||1))*h;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle='#69706a';ctx.font='12px system-ui';ctx.fillText(Math.round(max)+' m',2,16);ctx.fillText(Math.round(min)+' m',2,c.height-8);ctx.fillText('0',pad,c.height-4);ctx.fillText(g.dist.toFixed(1)+' km',c.width-58,c.height-4)}
