function iconInline(kind){const p={add:"<circle cx='12' cy='12' r='9'/><path d='M12 8v8M8 12h8'/>",refresh:"<path d='M20 7v5h-5'/><path d='M4 17v-5h5'/><path d='M18 12a6 6 0 0 0-10-4L4 12M6 12a6 6 0 0 0 10 4l4-4'/>",edit:"<path d='M4 20h4L19 9l-4-4L4 16v4Z'/><path d='m13.5 6.5 4 4'/>",trash:"<path d='M4 7h16M9 7V4h6v3M7 7l1 13h8l1-13M10 11v5M14 11v5'/>",rain:"<path d='M7 16h10a4 4 0 0 0 .5-8A6 6 0 0 0 6 9a3.5 3.5 0 0 0 1 7Z'/><path d='m9 19-1 2M13 19l-1 2M17 19l-1 2'/>",weather:"<circle cx='8' cy='8' r='3'/><path d='M8 2v2M2 8h2M12 4l1.5-1.5'/><path d='M8 18h9a3 3 0 0 0 0-6 5 5 0 0 0-9 2 2 2 0 0 0 0 4Z'/>"};return `<svg class='miniico' viewBox='0 0 24 24' aria-hidden='true'>${p[kind]||p.add}</svg>`}function iconNav(kind){const p={manage:"<rect x='4' y='5' width='16' height='14' rx='2'/><path d='m7 10 2 2 4-4'/><path d='M14 11h3M14 15h3'/>",check:"<circle cx='12' cy='12' r='9'/><path d='m8 12 3 3 5-6'/>"};return `<svg class='lineico' viewBox='0 0 24 24' aria-hidden='true'>${p[kind]}</svg>`}
function renderRoute(w){if(!w.gpx||!w.gpx.pts?.length){$('routeCard').classList.add('hidden');$('noRouteCard').classList.remove('hidden');$('addRouteCard').querySelector('b').innerHTML=iconInline('add')+'Adicionar percurso';return}$('noRouteCard').classList.add('hidden');$('routeCard').classList.remove('hidden');const g=w.gpx,allPois=g.waypoints||[],pois=activePois(g);$('sdist').textContent=g.dist.toFixed(1)+' km';$('sup').textContent='+'+Math.round(g.up)+' m';$('sdown').textContent='−'+Math.round(g.down)+' m';let about='';if(g.routeName||g.desc||pois.length){about=`<div class='gpxabout'>${g.routeName?`<b>${escapeHtml(g.routeName)}</b>`:''}${g.desc?`<p class='gpxdesc'>${escapeHtml(g.desc)}</p>`:''}${pois.length?`<div class='poirow'><b>Locais do percurso — ${pois.length}</b><ul id='poiList' class='poiList ${pois.length>8?'collapsed':''}'>${pois.map(x=>`<li class='${poiState(x.p)==='highlight'?'poiHighlight':''}' onclick='focusPoi(${x.i})'><span class='poidot'></span><span>${escapeHtml(poiLabel(x.p))}${poiState(x.p)==='highlight'?` <span class="poistar">★</span>`:''}${hasPoiPhotos(x.p)?' 📷':''}</span></li>`).join('')}</ul>${pois.length>8?`<button id='poiToggle' class='poitoggle' onclick='togglePois()'>Ver todos (${pois.length})</button>`:''}<button class='btn secondary small poiEditBtn' onclick="openPoiEditor(current.primaryRoute==='actual'&&current.actualGpx?'actual':'planned')">✎ Editar locais</button></div>`:''}</div>`}$('gpxInfo').innerHTML=about;if(map){map.remove();map=null}poiMarkers=[];map=L.map('map',{zoomControl:true});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);const ll=g.pts.map(p=>[p.lat,p.lon]);routeLine=L.polyline(ll,{weight:5,color:'#5B3426',opacity:.9}).addTo(map);L.circleMarker(ll[0],{radius:7,color:'#5B3426',fillColor:'#F4EBDD',fillOpacity:1,weight:3}).addTo(map).bindTooltip('Início');L.circleMarker(ll[ll.length-1],{radius:7,color:'#5B3426',fillColor:'#A84F2A',fillOpacity:1,weight:3}).addTo(map).bindTooltip('Fim');const pinIcon=p=>L.divIcon({className:'poi-pin'+(hasPoiPhotos(p)?' photoPin':''),html:'',iconSize:[16,16],iconAnchor:[8,15],popupAnchor:[0,-14]});poiMarkers=[];(g.waypoints||[]).forEach((p,i)=>{if(poiState(p)==='hidden'){poiMarkers[i]=null;return}const m=L.marker([p.lat,p.lon],{icon:pinIcon(p),title:poiLabel(p),opacity:poiState(p)==='highlight'?1:.82}).addTo(map).bindPopup(`<b>${escapeHtml(poiLabel(p))}${poiState(p)==='highlight'?' ★':''}</b>${p.desc?`<br>${escapeHtml(p.desc)}`:''}`);m.on('click',()=>selectPoi(i));poiMarkers[i]=m;attachPoiPopupPhoto(m,p)});map.fitBounds(routeLine.getBounds(),{padding:[15,15]});if(pois.length){$('map').insertAdjacentHTML('afterend',`<div class='maplegend'><span class='legendline'></span> Percurso <span class='legendpin'></span> Locais do GPX</div>`)}$('addRouteCard').querySelector('b').innerHTML=iconInline('refresh')+'Alterar percurso';drawElev(g);analyseRoute(g)}
