function gearItem(key,title,desc){const checked=!!current?.checklist?.[key];return `<div class='gearitem ${checked?'checked':''}' data-kind='${key}'><input type='checkbox' ${checked?'checked':''} onchange="toggleGear('${key}',this.checked)">${gearIcon(key)}<div class='gtxt'><b>${title}</b>${desc}</div></div>`}
function renderPreparation(w,previous){let d=+w.distance,up=w.gpx?w.gpx.up:0,x=w.weather,hot=x&&x.tmax>=25,cold=x&&x.tmin<=8,wet=x&&x.rain>=35,verywet=x&&x.rain>=60,windy=x&&x.wind>=30,steep=steepInfo(w.gpx),hasSteep=steep&&steep.grade>12;let small=d<=12&&up<700&&!cold;let water=d<=8?'0,75–1 L':d<=15?'1–1,5 L':'1,5–2 L';if(hot)water=d<=8?'1–1,5 L':d<=15?'1,5–2 L':'2 L ou mais';let shoe=wet?'Botas ou trail com boa aderência':'Sapatilhas de trail / calçado confortável';let rainTitle=!x?'Impermeável — por decidir':verywet?'Impermeável recomendado':wet?'Impermeável leve recomendado':x.rain<10?'Impermeável não necessário pela previsão':'Impermeável opcional';let rainDesc=!x?'Atualiza a meteorologia para decidir.':x.rain<10?`Chuva máxima prevista: ${Math.round(x.rain)}%. Um ultraleve fica apenas como precaução pessoal.`:`Probabilidade máxima de precipitação: ${Math.round(x.rain)}%.`;let poleRec=(up>=300&&hasSteep)||up>=500;let poleTitle=poleRec?'Bastões recomendados':'Bastões opcionais';let poleDesc=up?(poleRec?`+${Math.round(up)} m de subida acumulada${hasSteep?` e troço forte (~${Math.round(steep.grade)}%)`:''}.`:`Subida acumulada aproximada: +${Math.round(up)} m.`):'Sem desnível GPX conhecido.';$('gear').innerHTML=gearItem('backpack',`${small?'Mochila pequena':'Mochila média'}`,small?'Adequada à distância e condições previstas.':'Mais espaço para água, comida e camadas.')+gearItem('water','Água',`${water} por pessoa${hot?' — previsão quente.':''}`)+gearItem('food','Comida',d<=12?'Sandes + snack':'Refeição ligeira + snacks')+gearItem('shoes',shoe,wet?'Possibilidade de piso molhado/escorregadio.':'Ajusta ao tipo de terreno que conheces.')+gearItem('rain',rainTitle,rainDesc)+gearItem('poles',poleTitle,poleDesc)+(windy?gearItem('wind','Atenção ao vento',`Vento previsto até cerca de ${Math.round(x.wind)} km/h; atenção em zonas expostas.`):'');renderChanges(previous,x)}
function renderChanges(prev,now){if(!prev||!now){$('changes').innerHTML='';return}let c=[];if(prev.rain<35&&now.rain>=35)c.push(iconInline('rain')+'A chuva aumentou — impermeável passou a recomendado.');if(prev.rain>=35&&now.rain<35)c.push(iconInline('weather')+'A probabilidade de chuva diminuiu.');if(prev.tmax<25&&now.tmax>=25)c.push('Ficou mais quente — aumenta a água.');if(prev.wind<30&&now.wind>=30)c.push('O vento aumentou — atenção a zonas expostas.');$('changes').innerHTML=c.length?`<div class='notice warn'><b>${iconInline('refresh')}Desde a última atualização</b><br>${c.join('<br>')}</div>`:''}
async function locateWalk(w){if(w.gpx&&w.gpx.pts&&w.gpx.pts.length){const p=w.gpx.pts[0];return{lat:p.lat,lon:p.lon,label:w.place}}const u=`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(w.place)}&count=1&language=pt&format=json`;const r=await fetch(u);if(!r.ok)throw Error('geo');const j=await r.json();if(!j.results?.length)throw Error('geo');return{lat:j.results[0].latitude,lon:j.results[0].longitude,label:j.results[0].name}}
async function updateWeather(){if(!current)return;const b=$('weatherBtn'),old=current.weather?{...current.weather}:null;b.disabled=true;b.innerHTML='A atualizar…';try{const loc=await locateWalk(current),dur=Math.max(2,Math.min(12,Math.ceil((+current.distance/4)+(current.gpx?current.gpx.up/600:0))));const u=`https://api.open-meteo.com/v1/forecast?latitude=${loc.lat}&longitude=${loc.lon}&hourly=temperature_2m,precipitation_probability,weather_code,wind_speed_10m&timezone=auto&forecast_days=16`;const r=await fetch(u);if(!r.ok)throw Error('meteo');const j=await r.json(),start=`${current.date}T${current.time||'09:00'}`,si=j.hourly.time.findIndex(t=>t>=start);if(si<0)throw Error('range');const end=Math.min(j.hourly.time.length,si+dur),temps=j.hourly.temperature_2m.slice(si,end),rains=j.hourly.precipitation_probability.slice(si,end),winds=j.hourly.wind_speed_10m.slice(si,end),codes=j.hourly.weather_code.slice(si,end);if(!temps.length)throw Error('range');const x={tmin:Math.min(...temps),tmax:Math.max(...temps),rain:Math.max(...rains.map(v=>v??0)),wind:Math.max(...winds.map(v=>v??0)),code:codes[Math.floor(codes.length/2)]??codes[0],hours:dur,lat:loc.lat,lon:loc.lon,updatedAt:Date.now(),updatedLabel:new Date().toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'})};current.weather=x;persistCurrent();renderSavedWeather(current);renderPreparation(current,old)}catch(e){let m=e.message==='geo'?'Não consegui localizar esta caminhada. Se tiveres GPX, importa-o; caso contrário confirma o nome do local.':e.message==='range'?'A data está fora do período disponível da previsão meteorológica.':'Não consegui atualizar a meteorologia. Confirma a ligação à internet e tenta novamente.';$('weatherBox').innerHTML=`<div class='notice warn'>${m}</div>`}finally{b.disabled=false;b.innerHTML=`<svg class='uiico' viewBox='0 0 24 24'><path d='M20 7v5h-5'/><path d='M4 17v-5h5'/><path d='M18 12a6 6 0 0 0-10-4L4 12M6 12a6 6 0 0 0 10 4l4-4'/></svg>Atualizar preparação`}}

function exifReadJpeg(file){return new Promise((resolve)=>{const fr=new FileReader();fr.onload=()=>{try{const v=new DataView(fr.result);if(v.getUint16(0)!==0xFFD8)return resolve({error:'A fotografia não é JPEG.'});let off=2,ex=null;while(off+4<v.byteLength){if(v.getUint8(off)!==0xFF)break;const marker=v.getUint8(off+1),len=v.getUint16(off+2);if(marker===0xE1&&len>=8&&v.getUint32(off+4)===0x45786966){ex=off+10;break}off+=2+len}if(ex===null)return resolve({raw:'Sem bloco EXIF APP1.'});const le=v.getUint16(ex)===0x4949,u16=o=>v.getUint16(o,le),u32=o=>v.getUint32(o,le),base=ex,ifd0=base+u32(base+4);function entries(pos){const out={};const n=u16(pos);for(let i=0;i<n;i++){const e=pos+2+i*12;out[u16(e)]={type:u16(e+2),count:u32(e+4),val:e+8,ptr:u32(e+8)}}return out}function ascii(ent){if(!ent)return null;const bytes=(ent.type===2?1:1)*ent.count,pos=bytes<=4?ent.val:base+ent.ptr;let a='';for(let i=0;i<ent.count&&pos+i<v.byteLength;i++){const c=v.getUint8(pos+i);if(!c)break;a+=String.fromCharCode(c)}return a||null}function valuePos(ent){const bpt={1:1,2:1,3:2,4:4,5:8,7:1,9:4,10:8},bytes=(bpt[ent.type]||1)*ent.count;return bytes<=4?ent.val:base+ent.ptr}function ratAt(pos){const n=u32(pos),d=u32(pos+4);return d?n/d:null}function ratAtEndian(pos,signed=false){if(pos<0||pos+8>v.byteLength)return null;let n=signed?v.getInt32(pos,le):v.getUint32(pos,le),d=signed?v.getInt32(pos+4,le):v.getUint32(pos+4,le);return d?n/d:null}function ratsAt(ent,pos){if(!ent||(ent.type!==5&&ent.type!==10)||pos<0||pos+ent.count*8>v.byteLength)return null;const a=[];for(let i=0;i<ent.count;i++)a.push(ratAtEndian(pos+i*8,ent.type===10));return a}function plausibleGps(a){return a&&a.length>=3&&a.every(Number.isFinite)&&a[0]>=0&&a[0]<=180&&a[1]>=0&&a[1]<60&&a[2]>=0&&a[2]<60}function rats(ent,altBase){if(!ent)return null;const p1=valuePos(ent),a1=ratsAt(ent,p1);if(plausibleGps(a1))return {vals:a1,pos:p1,mode:'TIFF-base'};if(altBase!=null&&ent.count*8>4){const p2=altBase+ent.ptr,a2=ratsAt(ent,p2);if(plausibleGps(a2))return {vals:a2,pos:p2,mode:'GPS-IFD-base'};}return {vals:a1,pos:p1,mode:'TIFF-base (raw)'}}const e0=entries(ifd0),exifPtr=e0[0x8769],gpsPtr=e0[0x8825];let date=null,lat=null,lon=null,raw=[];if(exifPtr){const ee=entries(base+exifPtr.ptr);date=ascii(ee[0x9003])||ascii(ee[0x9004])}if(gpsPtr){const gpsPos=base+gpsPtr.ptr,ge=entries(gpsPos);raw.push('GPS IFD encontrado');raw.push('tags: '+Object.keys(ge).map(x=>'0x'+Number(x).toString(16)).join(', '));const lr=ascii(ge[1]),lor=ascii(ge[3]),lar=rats(ge[2],gpsPos),lorat=rats(ge[4],gpsPos),la=lar&&lar.vals,lo=lorat&&lorat.vals;raw.push('LatRef: '+String(lr));raw.push('Lat tag: type='+(ge[2]?.type)+' count='+(ge[2]?.count)+' ptr='+(ge[2]?.ptr));raw.push('Lat raw: '+JSON.stringify(la)+' @'+(lar?.pos)+' '+(lar?.mode));raw.push('LonRef: '+String(lor));raw.push('Lon tag: type='+(ge[4]?.type)+' count='+(ge[4]?.count)+' ptr='+(ge[4]?.ptr));raw.push('Lon raw: '+JSON.stringify(lo)+' @'+(lorat?.pos)+' '+(lorat?.mode));if(plausibleGps(la)){lat=la[0]+la[1]/60+la[2]/3600;if(lr==='S')lat=-lat}if(plausibleGps(lo)){lon=lo[0]+lo[1]/60+lo[2]/3600;if(lor==='W')lon=-lon}}else raw.push('GPS IFD não encontrado');resolve({date,lat,lon,raw:raw.join('\n')})}catch(e){resolve({error:'Não consegui ler os metadados desta fotografia.',raw:String(e)})}};fr.onerror=()=>resolve({error:'Não consegui abrir a fotografia.'});fr.readAsArrayBuffer(file)})}
async function resumePoiSession(){const ses=readPoiSession();if(!ses?.walkId)return false;const w=getWalks().find(x=>x.id===ses.walkId);if(!w){clearPoiSession();return false}current=w;await openPoiEditor(ses.target==='planned'?'planned':'actual');setTimeout(()=>window.scrollTo(0,Number.isFinite(ses.scrollY)?ses.scrollY:0),80);return true}
