(()=>{const BUILD=LEVABOTA_VERSION;window.LEVABOTA_BUILD=BUILD;async function verifyFreshBuild(){if(!navigator.onLine)return;try{const u=new URL('./index.html',location.href);u.searchParams.set('_buildcheck',Date.now());const r=await fetch(u,{cache:'no-store',headers:{'Cache-Control':'no-cache'}});if(!r.ok)return;const txt=await r.text();const m=txt.match(/<meta name=["']levabota-build["'] content=["']([^"']+)/i);if(m&&m[1]!==BUILD){location.replace('./?v='+encodeURIComponent(m[1])+'&_fresh='+Date.now())}}catch(e){}}window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')verifyFreshBuild()});window.addEventListener('focus',verifyFreshBuild);setTimeout(verifyFreshBuild,1200)})();
